businessProcess.setAutonumbering(true);

Task task = mdFactory.createTask();
task.setName(businessProcess.getName() + "Task");
task.setAutonumbering(true);
task.setUuid(UUID.randomUUID());
String taskFqn = fqnGenerator.generateStandaloneObjectFqn(task.eClass(), task.getName()).toString();
transaction.attachTopObject((IBmObject)task, taskFqn);
configuration.getTasks().add(task);
businessProcess.setTask(task);

